<?php require_once '../includes/role.php';requireRole('customer');require_once '../config/database.php';require_once '../includes/helpers.php';require_once '../includes/csrf.php';$s=$pdo->prepare('SELECT * FROM users WHERE id=? AND role="customer"');$s->execute([$_SESSION['user_id']]);$u=$s->fetch();$error='';$success='';if($_SERVER['REQUEST_METHOD']==='POST'){verify_csrf();$name=trim($_POST['name']??'');$phone=trim($_POST['phone']??'');$email=trim($_POST['email']??'');if($name===''||!filter_var($email,FILTER_VALIDATE_EMAIL))$error='Nama dan email harus valid.';else{try{$s=$pdo->prepare('SELECT id FROM users WHERE email=? AND id<>?');$s->execute([$email,$u['id']]);if($s->fetch())throw new Exception('Email sudah digunakan.');$s=$pdo->prepare('UPDATE users SET name=?,email=?,phone=? WHERE id=?');$s->execute([$name,$email,$phone?:null,$u['id']]);$_SESSION['user_name']=$name;$u=array_merge($u,['name'=>$name,'email'=>$email,'phone'=>$phone]);$success='Profil diperbarui.';}catch(Throwable $e){$error=servisku_error_message($e);}}}$pageTitle='Profil';require '../includes/customer_header.php';?><?php if($error):?><div class="alert"><?=e($error)?></div><?php endif;?><?php if($success):?><div class="success"><?=e($success)?></div><?php endif;?><section class="panel narrow"><div class="panel-heading"><h2>Profil Saya</h2></div><form method="post" class="compact-form"><input type="hidden" name="csrf_token" value="<?=e(csrf_token())?>"><label>Nama<input name="name" value="<?=e($u['name'])?>" required></label><label>Email<input type="email" name="email" value="<?=e($u['email'])?>" required></label><label>No. Telepon<input name="phone" value="<?=e($u['phone']??'')?>"></label><button>Simpan Perubahan</button></form></section><?php require '../includes/customer_footer.php';?>